#!/usr/bin/env python3
"""Offline exposition of proved general AC2 constructions and their scope."""
from pathlib import Path
import html,json,re
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[1]
def tex(value,display=True):
 return '<div class="math" data-tex="'+html.escape(value,quote=True)+'" data-display="'+str(display).lower()+'"></div>'
def p(text):return '<p>'+text+'</p>'
def main():
 css=re.search(r'<style>(.*?)</style>',(ROOT/'research/t2-spin2-inertia/index.html').read_text(),re.S).group(1)
 css='\n'.join(line.rstrip() for line in css.split('\n'))
 css+=' .math{overflow-x:auto;max-width:100%;padding:.45rem 0}.scroll-table{overflow-x:auto}table{border-collapse:collapse;width:100%}td,th{text-align:left;border-bottom:1px solid #deddd3;padding:.65rem}.recipe{background:#fffef9;border:1px solid #deddd3;padding:1.2rem;margin:1.4rem 0;border-radius:5px}details{margin:1.3rem 0}summary{cursor:pointer;font-weight:600}.downloads{display:grid;grid-template-columns:1fr 1fr;gap:.7rem}nav{display:flex;gap:1.1rem;flex-wrap:wrap;margin:1.5rem 0}li{margin:.5rem 0}@media(max-width:600px){.downloads{grid-template-columns:1fr}}'
 body='<p class="eyebrow">Anticoherent subspaces · General constructions</p><a href="../../index.html">← Return to the catalogue</a><h1>Constructing second-order AC subspaces</h1>'
 body+=p('There are explicit constructions valid for every qubit number from six onward, including a four-component family with dimension growing as N/8. Sharper prescriptions can also be certified in individual cases. A construction attaining the maximum dimension for every qubit number has not been proved.')
 body+='<div class="result"><strong>A universal analytical lower bound</strong>'+tex(r'K(N,2)\ge\left\lfloor\frac{N+3}{9}\right\rfloor,\qquad N\ge6.')+p('Each basis vector has only three nonzero Dicke coefficients, all square roots of positive rational numbers.')+'</div>'
 body+='<div class="result"><strong>Strengthened nested construction</strong>'+tex(r'K(N,2)\ge\left\lfloor\frac N8\right\rfloor-1,\qquad N\ge40.')+p('The refined four-band prescription improves the earlier bound by two dimensions. Separately certified nested examples now give 5 ≤ K(35,2) ≤ 8 and 6 ≤ K(42,2) ≤ 9. <a href="../t2-nesting-bounds/index.html">Read the new prescriptions and exact proofs ↗</a>')+'</div>'
 body+='<nav aria-label="On this page"><a href="#universal">Universal recipe</a><a href="#proof">All-N proof</a><a href="#four-band">Four-band family</a><a href="#adjacent">Adjacent triangles</a><a href="#cyclic">Cyclic prescription</a><a href="#improvements">Catalogue improvements</a><a href="#literature">Relation to known constructions</a></nav>'
 body+='<section id="universal"><h2>A basis with three components per vector</h2>'+p('Use normalized Dicke states and the convention')+tex(r'J_z|D_N^{(r)}\rangle=(j-r)|D_N^{(r)}\rangle,\qquad j=N/2.')+p('For the desired qubit number, calculate')
 body+=tex(r'k=\left\lfloor\frac{N+3}{9}\right\rfloor,\qquad h=\left\lfloor\frac{N-3(k-1)}2\right\rfloor,\qquad V=\frac{j(j+1)}3.')
 body+=p('For each basis index, set')+tex(r'\begin{aligned}a_i&=j-3i,&b_i&=a_i-h,&c_i&=a_i-2h,\qquad 0\le i<k,\\w_{i,0}&=\frac{V+b_ic_i}{2h^2},&w_{i,1}&=-\frac{V+a_ic_i}{h^2},&w_{i,2}&=\frac{V+a_ib_i}{2h^2}.\end{aligned}')
 body+='<div class="recipe">'+tex(r'\boxed{|u_i\rangle=\sqrt{w_{i,0}}|D_N^{(3i)}\rangle+\sqrt{w_{i,1}}|D_N^{(3i+h)}\rangle+\sqrt{w_{i,2}}|D_N^{(3i+2h)}\rangle.}')+p('These vectors are orthonormal, and every normalized complex superposition is second-order AC. There is no numerical optimization step in this recipe.')+'</div>'
 body+=p('<a href="separated-triples-bases.json">Example supports and exact rational weights ↓</a> · <a href="separated-bases.json">Analytical catalogue bases ↓</a>')+'</section>'
 body+='<section id="proof"><h2>Why the recipe works for every N</h2><h3>Spacing removes the off-diagonal spin moments</h3>'
 body+=p('Put')+tex(r'd=3(k-1),\qquad \epsilon=N-2h-d\in\{0,1\}.')
 body+=p('The definition of the dimension gives')+tex(r'N\ge9k-3\quad\Longrightarrow\quad h\ge3k,\qquad h-d\ge3.')
 body+=p('The occupied Dicke indices form three disjoint blocks, each with step three:')+tex(r'\{0,3,\ldots,d\},\quad\{h,h+3,\ldots,h+d\},\quad\{2h,2h+3,\ldots,2h+d\}.')
 body+=p('All indices lie between zero and N. Consecutive indices in the entire union are at least three apart. Operators shifting the Dicke index by one or two therefore have zero compression to the constructed span.')
 body+='<h3>The weights fix the required diagonal moments</h3>'+p('Direct substitution, or quadratic Lagrange interpolation, gives')+tex(r'\sum_{\ell=0}^2w_{i,\ell}=1,\qquad a_iw_{i,0}+b_iw_{i,1}+c_iw_{i,2}=0,\qquad a_i^2w_{i,0}+b_i^2w_{i,1}+c_i^2w_{i,2}=V.')
 body+='<h3>Every weight is strictly positive</h3>'+p('Both outside weights are positive because adjacent moment coordinates differ by h, so their products are bounded below by minus h squared over four:')+tex(r'a_ib_i\ge-\frac{h^2}4,\qquad b_ic_i\ge-\frac{h^2}4,\qquad \frac{h^2}4\le\frac{N^2}{16}<\frac{N(N+2)}{12}=V.')
 body+=p('For the middle weight, the following expression is concave in the basis index:')+tex(r'-a_ic_i=(j-3i)(2h-j+3i).')
 body+=p('Its minimum is at an endpoint. The endpoint values are respectively')+tex(r'j(j-d-\epsilon),\qquad (j-d)(j-\epsilon)=j(j-d-\epsilon)+d\epsilon.')
 body+=p('Consequently,')+tex(r'\begin{aligned}-a_ic_i-V&\ge j(j-d-\epsilon)-\frac{j(j+1)}3\\&=\frac j3\bigl(N-9k+8-3\epsilon\bigr)>0.\end{aligned}')
 body+=p('The strict inequality follows from N at least 9k minus 3 and epsilon at most one. Thus all square roots in the basis are well defined and nonzero.')
 body+='<h3>The entire complex span is AC</h3>'+p('Disjoint support, the moment identities, and the global spacing give the following compression identities for the projector P onto the span:')+tex(r'\begin{gathered}PJ_zP=0,\qquad PJ_z^2P=VP,\\PJ_+P=PJ_+^2P=P\{J_z,J_+\}P=0.\end{gathered}')
 body+=p('Their adjoints and the spin Casimir identity imply')+tex(r'PJ_\alpha P=0,\qquad P\frac{J_\alpha J_\beta+J_\beta J_\alpha}{2}P=V\delta_{\alpha\beta}P.')
 body+=p('These are exactly the first- and second-order AC conditions, including every cross term. The construction proves a lower bound; it does not assert that its dimension is the largest possible.')
 body+=p('<a href="separated-triples-proof.tex">Complete LaTeX proof ↓</a> · <a href="separated-triples-verification.json">Exact finite checks ↓</a> · <a href="separated-independent-verification.json">Independent catalogue-witness checks ↓</a>')+'</section>'
 body+='<section id="four-band"><h2>The original four-band family</h2>'+p('This earlier prescription established the one-eighth asymptotic rate. The new nested refinement linked above improves its constant from minus three to minus one:')+tex(r'\boxed{K(N,2)\ge\left\lfloor\frac N8\right\rfloor-3,\qquad N\ge40.}')+p('Write N in quotient–remainder form and define')+tex(r'\begin{gathered}N=8q+\rho,\quad0\le\rho\le7,\qquad k=q-3,\quad h=2q,\quad s=4+\lfloor\rho/2\rfloor,\\j=N/2,\qquad v=\frac{j(j+1)}{3h^2},\qquad x_i=\frac{j-s-2i}{h},\quad0\le i<k.\end{gathered}')
 body+=p('Use the following four positive rational weights:')+tex(r'\begin{aligned}w_0(x)&=\frac v4+\frac{x^2}4-\frac{35x}{36}+\frac56,&w_1(x)&=-\frac v4-\frac{x^2}4+\frac{5x}{12}+\frac12,\\w_2(x)&=-\frac v4-\frac{x^2}4+\frac{13x}{12}-\frac12,&w_3(x)&=\frac v4+\frac{x^2}4-\frac{19x}{36}+\frac16.\end{aligned}')
 body+=p('The basis vectors have the explicit supports')+tex(r'|u_i\rangle=\sum_{\ell=0}^3\sqrt{w_\ell(x_i)}\,\eta_{i\ell}|D_N^{(s+2i+\ell h)}\rangle,\qquad |\eta_{i\ell}|=1.')
 body+='<h3>Constructing the phases by a closed quadrilateral</h3>'+p('Begin with all four phases equal to one in the first vector. For each neighboring pair, define')+tex(r'\begin{gathered}r_{i\ell}=s+2i+\ell h,\\L_{i\ell}=\sqrt{w_\ell(x_i)w_\ell(x_{i+1})(r_{i\ell}+1)(r_{i\ell}+2)(N-r_{i\ell})(N-r_{i\ell}-1)}.\end{gathered}')
 body+=p('Choose d to be the midpoint of the following nonempty interval:')+tex(r'\left[\max\{|L_{i0}-L_{i1}|,|L_{i2}-L_{i3}|\},\;\min\{L_{i0}+L_{i1},L_{i2}+L_{i3}\}\right].')
 body+=p('For a pair of positive lengths a and b, set')+tex(r'\begin{aligned}c_a&=\frac{d^2+a^2-b^2}{2da},&c_b&=\frac{d^2+b^2-a^2}{2db},\\z_a&=c_a+\mathrm{i}\sqrt{1-c_a^2},&z_b&=c_b-\mathrm{i}\sqrt{1-c_b^2}.\end{aligned}')
 body+=p('These unit phases satisfy')+tex(r'a z_a+b z_b=d.')+p('Apply the formula first to the first two lengths and then to the last two. Update the resulting four phases by')+tex(r'(\eta_{i+1,0},\eta_{i+1,1},\eta_{i+1,2},\eta_{i+1,3})=(\eta_{i0}z_0,\eta_{i1}z_1,-\eta_{i2}z_2,-\eta_{i3}z_3).')
 body+=p('This completes the basis using rational arithmetic and square roots, with no optimization.')
 body+='<h3>Why the four-band prescription always succeeds</h3>'+p('The weights obey the three moment identities')+tex(r'\sum_\ell w_\ell(x)=1,\qquad\sum_\ell(x-\ell)w_\ell(x)=0,\qquad\sum_\ell(x-\ell)^2w_\ell(x)=v.')
 body+=p('The support bands have a gap of eight and a common parity. Hence the only surviving off-diagonal second-order entries join neighboring basis vectors within each band. The quadrilateral phase rule cancels those four contributions exactly.')
 body+='<details><summary>All-N positivity and quadrilateral certificate</summary>'+p('For each of the eight remainders, multiply the weights by 576q². After substituting q = i + z + 4, each resulting integer polynomial has nonnegative coefficients and a positive constant. This proves strict weight positivity throughout the basis range.')
 body+=p('For neighboring vectors, set')+tex(r'\begin{gathered}W_\ell=576q^2w_\ell(x_i),\\E_\ell=W_\ell(q,i)W_\ell(q,i+1)(r_{i\ell}+1)(r_{i\ell}+2)(N-r_{i\ell})(N-r_{i\ell}-1),\\q=i+z+5,\qquad i,z\ge0.\end{gathered}')
 body+=p('Define')+tex(r'F=\left(\sum_\ell E_\ell\right)^2-2\sum_\ell E_\ell^2,\qquad A=7421703487488\,(i^{14}z^2+i^2z^{14}).')
 body+=p('For all eight remainders, two finite polynomial expansions have exclusively nonnegative coefficients:')+tex(r'F+A\ge0,\qquad64E_0E_1E_2E_3-A^2\ge0.')
 body+=p('Thus the expression below is nonnegative:')+tex(r'F+8\sqrt{E_0E_1E_2E_3}=\prod_{\ell=0}^3\left(\sum_{m=0}^3\sqrt{E_m}-2\sqrt{E_\ell}\right)\ge0.')
 body+=p('With all lengths positive, at most one factor can be negative. The inequality is therefore equivalent to the four quadrilateral inequalities, proving the diagonal interval is nonempty. Both the primary symbolic certificate and an independent audit check every polynomial coefficient. These are exact all-N assertions, not an extrapolation from numerical examples.')+'</details>'
 body+=p('The original two universal families gave the following bound; the strengthened nested prescription above replaces the second term by floor(N/8) − 1:')+tex(r'K(N,2)\ge\max\!\left\{\left\lfloor\frac{N+3}{9}\right\rfloor,\left\lfloor\frac N8\right\rfloor-3\right\},\qquad N\ge40.')
 body+=p('This improves the asymptotic lower bound. It still leaves a gap to the general upper bound and does not establish maximum dimension for every N.')
 body+=p('<a href="four-band-proof.tex">Complete four-band proof ↓</a> · <a href="four-band-certificate.json">Exact all-N certificate ↓</a> · <a href="fourband-independent-audit.json">Independent audit ↓</a> · <a href="four_bands.py">Construction and verifier ↓</a> · <a href="construct_exact.py">Exact basis generator ↓</a> · <a href="four-band-n40-exact.json">Exact N = 40 example ↓</a>')+'</section>'
 body+='<section id="adjacent"><h2>A sharper prescription using triangle closure</h2>'+p('Allow neighboring basis vectors to occupy Dicke indices two apart. The remaining second-order cross terms can then cancel through explicit phases.')
 body+=p('Choose integers k, h, and o satisfying')+tex(r'h\text{ even},\qquad h\ge2k+2,\qquad o\ge0,\qquad o+2(k-1)+2h\le N.')
 body+=p('Set the three supports and their moment coordinates to')+tex(r'r_{i\ell}=o+2i+\ell h,\qquad m_{i\ell}=j-r_{i\ell},\qquad 0\le i<k,\quad0\le\ell\le2.')
 body+=p('Calculate the unique moment-matching weights and require each to be positive:')+tex(r'w_{i\ell}=\frac{V+m_{ia}m_{ib}}{(m_{i\ell}-m_{ia})(m_{i\ell}-m_{ib})},\qquad \{a,b,\ell\}=\{0,1,2\}.')
 body+=p('For each consecutive pair of vectors, calculate')+tex(r'\begin{aligned}A_{i\ell}&=w_{i\ell}w_{i+1,\ell}(N-r_{i\ell})(N-r_{i\ell}-1)(r_{i\ell}+1)(r_{i\ell}+2),\\\Delta_i&=2(A_{i0}A_{i1}+A_{i1}A_{i2}+A_{i2}A_{i0})-(A_{i0}^2+A_{i1}^2+A_{i2}^2).\end{aligned}')
 body+=p('Require every discriminant to be nonnegative. This is the exact condition that the three lengths form a closed triangle. Define its phases by')+tex(r'\begin{aligned}z_{i0}&=1,\\z_{i1}&=\frac{A_{i2}-A_{i0}-A_{i1}+\mathrm{i}\sqrt{\Delta_i}}{2\sqrt{A_{i0}A_{i1}}},\\z_{i2}&=-\frac{\sqrt{A_{i0}}+\sqrt{A_{i1}}z_{i1}}{\sqrt{A_{i2}}}.\end{aligned}')
 body+=p('Starting with unit phases in the first vector, multiply these phase increments along the chain:')+tex(r'q_{0\ell}=1,\qquad q_{i+1,\ell}=q_{i\ell}z_{i\ell},\qquad |u_i\rangle=\sum_{\ell=0}^2\sqrt{w_{i\ell}}q_{i\ell}|D_N^{(r_{i\ell})}\rangle.')
 body+=p('All phase factors have modulus one. Parity removes the odd shifts; the band spacing removes shifts between bands. The only remaining cross terms are exactly the closed triangles:')+tex(r'\langle u_i|J_+^2|u_{i+1}\rangle=\sum_{\ell=0}^2\sqrt{A_{i\ell}}z_{i\ell}=0.')
 body+=p('Thus every successful choice of the integer parameters gives an analytical AC2 subspace. This is a sufficient test, not a guarantee of success or optimality for every requested dimension.')
 body+='<h3>An explicit improvement at N = 22</h3>'+p('Choose k = 3, h = 8, and o = 1. Let')+tex(r'z=\frac{-37+\mathrm{i}\sqrt{9551}}{2\sqrt{2730}},\qquad w=\frac{-5-\mathrm{i}\sqrt{9551}}{6\sqrt{266}}.')
 body+=tex(r'\begin{aligned}|u_1\rangle&=\frac12|D_{22}^{(1)}\rangle+\frac12|D_{22}^{(9)}\rangle+\frac1{\sqrt2}|D_{22}^{(17)}\rangle,\\|u_2\rangle&=\sqrt{\frac{11}{32}}|D_{22}^{(3)}\rangle+\frac{\sqrt5}{4}z|D_{22}^{(11)}\rangle+\sqrt{\frac{11}{32}}w|D_{22}^{(19)}\rangle,\\|u_3\rangle&=\frac1{\sqrt2}|D_{22}^{(5)}\rangle+\frac w2|D_{22}^{(13)}\rangle+\frac{w^2}2|D_{22}^{(21)}\rangle.\end{aligned}')
 body+=p('This proves a lower bound of three; the current upper bound is five. <a href="../../index.html#n=22&amp;t=2&amp;subspace=adjacent-triples-n22-k3-t2">Inspect the N = 22 basis ↗</a>')
 body+=p('<a href="adjacent-triples-proof.tex">Triangle-construction proof ↓</a> · <a href="adjacent-triples.json">Exact basis and parameters ↓</a> · <a href="adjacent-triples-verification.json">Exact verification ↓</a>')+'</section>'
 body+='<section id="cyclic"><h2>A cyclic prescription aimed at the upper bound</h2>'+p('For a target dimension k, assign one basis vector to each Dicke residue modulo k:')+tex(r'|u_a\rangle=\sum_{\ell:\,a+k\ell\le N}c_{a\ell}|D_N^{(a+k\ell)}\rangle,\qquad 0\le a<k.')
 body+=p('Disjoint support gives orthogonality. Solve the diagonal conditions')+tex(r'\sum_\ell|c_{a\ell}|^2=1,\qquad\sum_\ell(j-a-k\ell)|c_{a\ell}|^2=0,\qquad\sum_\ell(j-a-k\ell)^2|c_{a\ell}|^2=V,')
 body+=p('together with the following conditions for all ordered pairs (including equal indices)')+tex(r'\langle u_a|J_+|u_b\rangle=\langle u_a|\{J_z,J_+\}|u_b\rangle=\langle u_a|J_+^2|u_b\rangle=0.')
 body+=p('Only residues separated by one or two can couple. Reflection can further reduce the independent coefficients. Writing each Dicke amplitude as the square root of its binomial coefficient times a complex variable converts the equations into polynomials with integer coefficients. An isolated numerical solution can then be promoted to an exact algebraic construction using a rational contraction certificate.')
 body+='<div class="recipe"><strong>A new optimal instance</strong>'+tex(r'\boxed{K(24,2)=5}.')+p('Five residue classes modulo five, paired by unitary reflection, reduce to 23 real quadratic equations. Exact rational contraction proves a unique solution, and every two-qubit cross reduction is certified. The coefficients have an explicit isolated algebraic definition.')+p('<a href="n24-k5/index.html">Read the analytical basis and existence proof ↗</a>')+'</div>'
 body+=p('The general upper bound gives')+tex(r'K(N,2)\le\min\!\left\{\left\lfloor\frac{N-2}{4}\right\rfloor,\left\lfloor\frac{N+5}{5}\right\rfloor\right\},\qquad N\ge8.')
 body+=p('At N = 24 the upper bound is five, so the construction is maximal without imposing symmetry on competing subspaces. General feasibility remains open. A separate theorem now excludes all upper-dimension subspaces with this cyclic invariance for N ≥ 420 (and for N = 5k − 1 once k ≥ 62). This rules out an infinite saturating family with the prescribed cyclic symmetry; it does not exclude nonsymmetric saturating subspaces. <a href="../t2-saturation/index.html">Read the cyclic-invariance obstruction and proof ↗</a> Numerical search failures themselves are not exclusion proofs.')+'</section>'
 body+=p('<a href="../t2-nested-t1/index.html">Constructing second-order subspaces inside first-order parents: an exact pairing recipe and extension theorem ↗</a>')
 body+='<section id="improvements"><h2>Improvements obtained from these prescriptions</h2><div class="scroll-table"><table><thead><tr><th>Qubits N</th><th>Previous lower bound</th><th>New lower bound</th><th>Current upper bound</th><th>Construction</th></tr></thead><tbody>'
 rows=[(22,2,3,5,'Adjacent triangles','../../index.html#n=22&t=2&subspace=adjacent-triples-n22-k3-t2'),(24,3,5,5,'Cyclic algebraic basis; proved maximum','n24-k5/index.html'),(35,4,5,8,'Certified nested parity basis','../../index.html#n=35&t=2&subspace=algebraic-parity-n35-k5-t2'),(42,5,6,9,'Certified nested parity basis','../../index.html#n=42&t=2&subspace=algebraic-parity-n42-k6-t2')]
 for n,old,new,upper,label,href in rows:body+=f'<tr><td>{n}</td><td>{old}</td><td>{new}</td><td>{upper}</td><td><a href="{html.escape(href,quote=True)}">{label} ↗</a></td></tr>'
 body+='</tbody></table></div>'+p('These entries retain their rigorous upper bounds. Only the N = 24 entry is settled by the new constructions.')+'</section>'
 body+='<section id="literature"><h2>Relation to known constructions</h2>'+p('Tetrahedral invariant polynomials provide another general route to AC2 subspaces: take independent homogeneous invariants of degree N, map their coefficients to Dicke amplitudes, and orthonormalize. The catalogue already includes these Molien constructions. They are not a general maximum-dimension theorem. <a href="https://arxiv.org/abs/1610.05841">Pereira and Paul-Paddock, Anticoherent Subspaces ↗</a>')
 body+=p('Tverberg constructions of permutation-invariant and spin error-correcting codes guarantee common moments between codewords. Second-order anticoherence additionally fixes those common moments to zero dipole and isotropic variance j(j+1)/3. A distance-three code therefore requires this extra check before it can be imported as an AC2 subspace. <a href="https://arxiv.org/abs/2509.20545">Aydin, Albert, and Barg, Quantum error correction beyond SU(2) ↗</a>')
 body+=p('The separated-triple and adjacent-triangle constructions above impose the required AC moments explicitly, and their proofs include every cross term. They are catalogue calculations, distinct from a claim that arbitrary error-correcting codes are anticoherent.')+'</section><footer><p>Anticoherent subspaces · 30 October 2026</p><a href="../../index.html">Return to the catalogue ↗</a></footer>'
 head='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>General constructions of second-order AC subspaces</title><link rel="stylesheet" href="../../vendor/katex/katex.min.css"><script defer src="../../vendor/katex/katex.min.js"></script><style>'+css+'</style><script>document.addEventListener("DOMContentLoaded",()=>document.querySelectorAll("[data-tex]").forEach(el=>{if(window.katex)el.innerHTML=katex.renderToString(el.dataset.tex,{displayMode:el.dataset.display==="true",throwOnError:false,strict:"ignore",trust:false});}));</script></head><body><main>'
 (HERE/'index.html').write_text(head+body+'</main></body></html>\n')
if __name__=='__main__':main()
